/**
 * 认证方式。
 */
sealed class AuthMethod {
    
    data class Password(
        val `password`: kotlin.String) : AuthMethod()
        
    {
        

        companion object
    }
    
    data class KeyFile(
        val `path`: kotlin.String, 
        val `passphrase`: kotlin.String?) : AuthMethod()
        
    {
        

        companion object
    }
    
    /**
     * 私钥内容(导入后加密存在应用里,连接时在内存里解密传过来)。
     */
    data class KeyData(
        val `pem`: kotlin.String, 
        val `passphrase`: kotlin.String?) : AuthMethod()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAuthMethod : FfiConverterRustBuffer<AuthMethod>{
    override fun read(buf: ByteBuffer): AuthMethod {
        return when(buf.getInt()) {
            1 -> AuthMethod.Password(
                FfiConverterString.read(buf),
                )
            2 -> AuthMethod.KeyFile(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            3 -> AuthMethod.KeyData(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AuthMethod): ULong = when(value) {
        is AuthMethod.Password -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`password`)
            )
        }
        is AuthMethod.KeyFile -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`path`)
                + FfiConverterOptionalString.allocationSize(value.`passphrase`)
            )
        }
        is AuthMethod.KeyData -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`pem`)
                + FfiConverterOptionalString.allocationSize(value.`passphrase`)
            )
        }
    }

    override fun write(value: AuthMethod, buf: ByteBuffer) {
        when(value) {
            is AuthMethod.Password -> {
                buf.putInt(1)
                FfiConverterString.write(value.`password`, buf)
                Unit
            }
            is AuthMethod.KeyFile -> {
                buf.putInt(2)
                FfiConverterString.write(value.`path`, buf)
                FfiConverterOptionalString.write(value.`passphrase`, buf)
                Unit
            }
            is AuthMethod.KeyData -> {
                buf.putInt(3)
                FfiConverterString.write(value.`pem`, buf)
                FfiConverterOptionalString.write(value.`passphrase`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * 错误(flat_error:只有变体名和 Display 文本跨边界,字段不过去)。
 *
 * 两个主机密钥变体的 Display **就是服务端指纹本身**,不加任何说明文字 ——
 * 宿主要拿它去存/去比对,掺了人话就得反过来解析字符串。给人看的措辞由 UI 拼,
 * 已信任的那个指纹本来就在宿主手里。
 */
sealed class FfiException(message: String): kotlin.Exception(message) {
        
        class Message(message: String) : FfiException(message)
        
    /**
     * 首次见到这台主机的密钥,需要用户确认。
     */
        class HostKeyUnknown(message: String) : FfiException(message)
        
    /**
     * 主机密钥与已信任的不一致,连接已拒绝。
     */
        class HostKeyChanged(message: String) : FfiException(message)
        
    /**
     * 同上两条,但说的是**跳板机**的密钥 —— 宿主要把指纹存到跳板机那台主机上,不是目标。
     */
        class JumpHostKeyUnknown(message: String) : FfiException(message)
        
        class JumpHostKeyChanged(message: String) : FfiException(message)
        
    /**
     * 私钥带口令,没给或给错了(导入 / 连接时界面据此提示填口令)。
     */
        class KeyEncrypted(message: String) : FfiException(message)
        
    /**
     * 传输被用户取消(不是错误,界面不用提示)。
     */
        class Cancelled(message: String) : FfiException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        
            return when(buf.getInt()) {
            1 -> FfiException.Message(FfiConverterString.read(buf))
            2 -> FfiException.HostKeyUnknown(FfiConverterString.read(buf))
            3 -> FfiException.HostKeyChanged(FfiConverterString.read(buf))
            4 -> FfiException.JumpHostKeyUnknown(FfiConverterString.read(buf))
            5 -> FfiException.JumpHostKeyChanged(FfiConverterString.read(buf))
            6 -> FfiException.KeyEncrypted(FfiConverterString.read(buf))
            7 -> FfiException.Cancelled(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: FfiException): ULong {
        return 4UL
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Message -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.HostKeyUnknown -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.HostKeyChanged -> {
                buf.putInt(3)
                Unit
            }
            is FfiException.JumpHostKeyUnknown -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.JumpHostKeyChanged -> {
                buf.putInt(5)
                Unit
            }
            is FfiException.KeyEncrypted -> {
                buf.putInt(6)
                Unit
            }
            is FfiException.Cancelled -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



